example.text:
SELECT contactLastName, contactFirstName
FROM customers
ORDER BY contactLastName ASC;

SELECT contactLastName, contactFirstName
FROM customers
ORDER BY contactLastName DESC, contactFirstName ASC;

SELECT lastName, firstName
FROM employees
WHERE jobTitle = 'Sales Rep';

SELECT lastName, jobTitle
FROM employees
WHERE jobTitle = 'Sales Rep';

SELECT lastName, officeCode
FROM employees
WHERE jobTitle = 'Sales Rep' AND officeCode = 1;

SELECT lastName
FROM employees
WHERE NOT (jobTitle = 'Sales Rep');

SELECT customerName, country, state
FROM customers
WHERE country = 'USA' AND state = 'CA';

SELECT customerName, country
FROM customers
WHERE country = 'USA' OR country = 'France';

SELECT m.member_id, m.name AS member, c.committee_id
FROM members AS m
INNER JOIN committees AS c ON c.name = m.name;

SELECT productCode, productName, textDescription
FROM products
INNER JOIN productlines USING (productLine);

SELECT m.member_id, m.name, c.committee_id
FROM members AS m
LEFT JOIN committees AS c USING (name);

SELECT c.customerNumber, c.customerName, o.orderNumber, o.status
FROM customers AS c
LEFT JOIN orders AS o ON o.customerNumber = c.customerNumber;

SELECT m.member_id, m.name AS member, c.committee_id
FROM members AS m
RIGHT JOIN committees AS c ON c.name = m.name;
